const q = $json.query || {};
if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === 'instagram-webhook') {
  return [{ json: { challenge: q['hub.challenge'] } }];
}
return [{ json: { error: 'invalid token' } }];

const body = $json.body || {};
const messaging = body.entry?.[0]?.messaging?.[0] || {};
if (messaging.is_echo === true) return [];
const text = (messaging.message?.text || '').trim();
if (!text) return [];

const referral = messaging.referral || {};
const adRef = (referral.ref || '').trim();        // ref parameter configurado en el anuncio
const adId  = (referral.ad_id || '').trim();       // ID del anuncio de Meta
const adSource = (referral.source || '').trim();   // ej: 'ADS'

return [{ json: {
  user_id: messaging.sender?.id || null,
  message_text: text,
  ad_ref: adRef,
  ad_id: adId,
  ad_source: adSource
} }];

const text = $json.message_text.toLowerCase();
const fitmentKW = ['toyota','honda','ford','chevrolet','hyundai','kia','nissan','mazda','ram','mitsubishi','suzuki','subaru','volkswagen','jeep','dodge','gmc','hilux','fortuner','rav4','4runner','prado','runner','tacoma','tundra','corolla','camry','yaris','crv','hrv','civic','accord','ranger','explorer','silverado','tahoe','tucson','santafe','sportage','sorento','frontier','pathfinder','cx5','cx-5','outlander','montero','vitara','forester','outback','tengo un','mi carro','mi vehículo','mi vehiculo','tengo una','pick up','pickup','camioneta','suv'];
const stockKW = ['precio','costo','cuánto','cuanto','disponible','stock','inventario','tienen','hay','comprar','pagar','vale','sale','oferta','promo'];
const intent = fitmentKW.some(kw => text.includes(kw)) ? 'FITMENT' : stockKW.some(kw => text.includes(kw)) ? 'STOCK' : 'GENERAL';
return [{ json: { ...$json, intent } }];

const rawContent = $json.choices[0].message.content.trim();
const filterNode = $('Filter & Normalize').item.json;
const userId = filterNode.user_id;
const messageText = filterNode.message_text;
const adRef = filterNode.ad_ref || '';
const adId = filterNode.ad_id || '';
const adSource = filterNode.ad_source || '';

let entity = { brand: null, model: null, year: null };
try {
  const clean = rawContent.replace(/```json|```/g, '').trim();
  entity = JSON.parse(clean);
} catch (e) {
  return [{ json: { sql: null, user_id: userId, message_text: messageText, intent: 'FITMENT', ad_ref: adRef, ad_id: adId, ad_source: adSource, no_vehicle_detected: true, debug: { parseError: e.message } } }];
}

const { brand, model, year } = entity;
if (!brand && !model) {
  return [{ json: { sql: null, user_id: userId, message_text: messageText, intent: 'FITMENT', ad_ref: adRef, ad_id: adId, ad_source: adSource, no_vehicle_detected: true, debug: { brand, model, year } } }];
}

const brandClause = brand ? `AND v.brand ILIKE '%${brand.replace(/'/g, "''")}%'` : '';
const modelClause = model ? `AND v.model ILIKE '%${model.replace(/'/g, "''")}%'` : '';
const yearClause = year ? `AND v.year_start <= ${year} AND (v.year_end >= ${year} OR v.year_end >= 9999)` : '';

const sql = `
  SELECT v.brand AS vehicle_brand, v.model AS vehicle_model, v.year_start AS year_from, v.year_end AS year_to,
    v.roof_type, p.sku AS fitment_sku, p.name AS product_name, p.category AS product_category,
    fmap.store_product_code, tps.title AS store_title,
    tps.price_amount, tps.currency, tps.stock_status, tps.promo_text,
    vpf.fitment_notes, vpf.pad_type
  FROM vehicles v
  JOIN vehicle_product_fitment vpf ON vpf.vehicle_id = v.id
  JOIN products p ON p.sku = vpf.product_sku
  LEFT JOIN fitment_store_sku_map fmap ON fmap.fitment_sku = p.sku
  LEFT JOIN tecbite_product_state tps ON tps.product_sku = fmap.store_product_code AND tps.is_active = true
  WHERE vpf.is_compatible = true ${brandClause} ${modelClause} ${yearClause}
  ORDER BY tps.price_amount ASC NULLS LAST
  LIMIT 6;
`;

return [{ json: { sql, user_id: userId, message_text: messageText, intent: 'FITMENT', ad_ref: adRef, ad_id: adId, ad_source: adSource, year, no_vehicle_detected: false, debug: { brand, model, year } } }];

const text = $json.message_text;
const textLower = text.toLowerCase();

// Detectar marca mencionada
const mentionsThule = textLower.includes('thule');
const mentionsWT = textLower.includes('weathertech') || textLower.includes('weather tech');

// Filtro de marca: solo la mencionada. Si ninguna o ambas → incluir las dos
let brandClause;
if (mentionsWT && !mentionsThule) {
  brandClause = "tps.brand ILIKE '%WeatherTech%'";
} else if (mentionsThule && !mentionsWT) {
  brandClause = "tps.brand ILIKE '%Thule%'";
} else {
  brandClause = "(tps.brand ILIKE '%Thule%' OR tps.brand ILIKE '%WeatherTech%')";
}

const sql = `
  SELECT tps.product_sku AS sku, tps.title, tps.brand, tps.category,
    tps.price_amount, tps.currency, tps.stock_status, tps.promo_text
  FROM tecbite_product_state tps
  WHERE tps.is_active = true
    AND ${brandClause}
  ORDER BY
    CASE tps.stock_status WHEN 'in_stock' THEN 1 WHEN 'out_of_stock' THEN 2 ELSE 3 END,
    tps.price_amount ASC
  LIMIT 5;
`;

const filterNode2 = $('Filter & Normalize').item.json;
const adRef2 = filterNode2.ad_ref || '';
const adId2 = filterNode2.ad_id || '';
const adSource2 = filterNode2.ad_source || '';

return [{ json: { sql, user_id: $json.user_id, message_text: text, intent: 'STOCK', ad_ref: adRef2, ad_id: adId2, ad_source: adSource2, debug: { mentionsThule, mentionsWT } } }];

// CONTEXT BUILDER
// El nodo Postgres elimina el JSON original. Leemos user_id y message_text
// directamente desde Filter & Normalize para no perderlos.
const items = $input.all();
const first = items[0]?.json || {};

const filterNode = $('Filter & Normalize').item.json;
const userId = filterNode.user_id;
const messageText = filterNode.message_text;
const adRef = filterNode.ad_ref || '';
const adId = filterNode.ad_id || '';
const adSource = filterNode.ad_source || '';

// Inferir intent desde las columnas SQL
const intent = first.vehicle_brand ? 'FITMENT' : first.sku ? 'STOCK' : 'GENERAL';

let contextText = '';

if (intent === 'FITMENT') {
  if (items.length === 0 || !first.vehicle_brand) {
    contextText = 'No hay productos compatibles en nuestro catálogo para ese vehículo aún.';
  } else {
    const withPrice = items.filter(i => i.json.price_amount && parseFloat(i.json.price_amount) > 0);
    const withoutPrice = items.filter(i => !i.json.price_amount || parseFloat(i.json.price_amount) === 0);
    if (withPrice.length > 0) {
      contextText = 'PRODUCTOS COMPATIBLES CON PRECIO:\n';
      withPrice.forEach(item => {
        const i = item.json;
        const yearTo = i.year_to >= 9999 ? 'presente' : i.year_to;
        contextText += `• ${i.vehicle_brand} ${i.vehicle_model} (${i.year_from}-${yearTo})`;
        contextText += ` | ${i.store_title || i.product_name}`;
        contextText += ` | $${i.price_amount} ${i.currency} | Stock: ${i.stock_status}`;
        if (i.promo_text) contextText += ` | PROMO: ${i.promo_text}`;
        if (i.fitment_notes) contextText += ` | Nota: ${i.fitment_notes}`;
        contextText += '\n';
      });
    }
    if (withoutPrice.length > 0) {
      contextText += `\nACCESORIOS ADICIONALES COMPATIBLES (sin precio cargado aún): ${withoutPrice.map(i => i.json.product_name).join(', ')}\n`;
    }
  }
} else if (intent === 'STOCK') {
  if (items.length === 0 || !first.sku) {
    contextText = 'No encontré productos de esa marca en nuestro inventario activo.';
  } else {
    contextText = 'PRODUCTOS DISPONIBLES:\n';
    items.forEach(item => {
      const i = item.json;
      contextText += `• SKU: ${i.sku} | ${i.title} (${i.brand})`;
      contextText += ` | $${i.price_amount} ${i.currency} | Stock: ${i.stock_status}`;
      if (i.promo_text) contextText += ` | PROMO: ${i.promo_text}`;
      contextText += '\n';
    });
  }
}

return [{ json: { user_id: userId, message_text: messageText, db_context: contextText, intent, ad_ref: adRef, ad_id: adId, ad_source: adSource } }];

// Construye el payload de DeepSeek de forma segura con JSON.stringify
const dbContext = $json.db_context || '';
const messageText = $json.message_text;
const userId = $json.user_id;
const intent = $json.intent || 'GENERAL';
const adRef = $json.ad_ref || '';
const adId = $json.ad_id || '';

// Regla de vehículo: solo aplica para FITMENT, NO para STOCK
const vehicleRule = intent === 'FITMENT'
  ? '- Si el usuario no ha indicado marca, modelo y año de su vehículo, pídeselos antes de recomendar.'
  : '- NO pidas datos del vehículo para preguntas de precio o stock. Muestra lo disponible directamente.';

// Contexto del anuncio: si el usuario vino de un ad, sabemos de qué producto habla
const adContext = adRef
  ? `\nCONTEXTO DEL ANUNCIO DE INSTAGRAM:\n- El usuario hizo clic en un anuncio. Referencia: ${adRef}${adId ? ' (Ad ID: ' + adId + ')' : ''}\n- SI el usuario pregunta por precio, stock o disponibilidad SIN especificar producto, asume que se refiere al producto del anuncio.\n- Usa la referencia del anuncio para inferir marca y categoría antes de preguntar detalles.`
  : '';

const systemPrompt = `Eres el asesor virtual de Tecbite Panama, especialista en accesorios Thule y WeatherTech.

REGLAS:
- Sé amable, breve y directo. Máximo 3 párrafos cortos.
${vehicleRule}
- NUNCA inventes precios ni SKUs. Usa SOLO los datos que te dan en CONTEXTO.
- Si no hay datos en contexto o el stock es 0, sé honesto y ofrece contacto por Instagram.
- Si hay PROMO en el contexto, mencionalo con entusiasmo.
- Responde SIEMPRE en español.
${adContext}

CONTEXTO DE BASE DE DATOS:
${dbContext || 'Sin contexto SQL (consulta general).'}`;

const payload = {
  model: 'deepseek-chat',
  max_tokens: 400,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: messageText }
  ]
};

return [{ json: { payload: JSON.stringify(payload), user_id: userId } }];
